m=A.b([new A.fa("Construction Contracting","\u0645\u0642\u0627\u0648\u0644\u0627\u062a \u0627\u0644\u0628\u0646\u0627\u0621","We undertake all construction works from foundation to handover, accurately and professionally.","\u0646\u062a\u0648\u0644\u0649 \u062c\u0645\u064a\u0639 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0628\u0646\u0627\u0621 \u0645\u0646 \u0627\u0644\u0623\u0633\u0627\u0633\u0627\u062a \u062d\u062a\u0649 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0628\u062f\u0642\u0629 \u0648\u0627\u062d\u062a\u0631\u0627\u0641\u064a\u0629.",B.GU),new A.fa("Electrical Works","\u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629","Specialized electrical personnel applying full safety procedures for every project.","\u0643\u0648\u0627\u062f\u0631 \u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629 \u0645\u062a\u062e\u0635\u0635\u0629 \u062a\u0637\u0628\u0642 \u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0641\u064a \u0643\u0644 \u0645\u0634\u0631\u0648\u0639.",B.GV),new A.fa("Sanitary Works","\u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u062d\u064a\u0629","Skilled supervisors ensuring efficient implementation of all sanitary works.","\u0645\u0634\u0631\u0641\u0648\u0646 \u0645\u0647\u0631\u0629 \u064a\u0636\u0645\u0646\u0648\u0646 \u062a\u0646\u0641\u064a\u0630\u0627\u064b \u0643\u0641\u0624\u0627\u064b \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u062d\u064a\u0629.",B.H1),new A.fa("Gypsum And Decoration","\u0627\u0644\u062c\u0628\u0633 \u0648\u0627\u0644\u062f\u064a\u0643\u0648\u0631","International team creating gypsum and decoration works with high professionalism.","\u0641\u0631\u064a\u0642 \u062f\u0648\u0644\u064a \u064a\u0646\u0641\u0630 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062c\u0628\u0633 \u0648\u0627\u0644\u062f\u064a\u0643\u0648\u0631 \u0628\u0627\u062d\u062a\u0631\u0627\u0641\u064a\u0629 \u0639\u0627\u0644\u064a\u0629.",B.GX),new A.fa("Duct Cleaning For A/C","\u062a\u0646\u0638\u064a\u0641 \u0645\u062c\u0627\u0631\u064a \u0627\u0644\u062a\u0643\u064a\u064a\u0641","Specialized team cleaning ducts from impurities using advanced equipment.","\u0641\u0631\u064a\u0642 \u0645\u062a\u062e\u0635\u0635 \u064a\u0646\u0638\u0641 \u0645\u062c\u0627\u0631\u064a \u0627\u0644\u0647\u0648\u0627\u0621 \u0645\u0646 \u0627\u0644\u0634\u0648\u0627\u0626\u0628 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0639\u062f\u0627\u062a \u0645\u062a\u0637\u0648\u0631\u0629.",B.GK),new A.fa("Cleaning Work","\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062a\u0646\u0638\u064a\u0641","External cleaning for high-rise glass buildings using high-tech equipment.","\u062a\u0646\u0638\u064a\u0641 \u062e\u0627\u0631\u062c\u064a \u0644\u0644\u0645\u0628\u0627\u0646\u064a \u0627\u0644\u0632\u062c\u0627\u062c\u064a\u0629 \u0627\u0644\u0634\u0627\u0647\u0642\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0639\u062f\u0627\u062a \u062a\u0642\u0646\u064a\u0629 \u0645\u062a\u0642\u062f\u0645\u0629.",B.GS),new A.fa("Water & Thermal Insulation","\u0627\u0644\u0639\u0632\u0644 \u0627\u0644\u0645\u0627\u0626\u064a \u0648\u0627\u0644\u062d\u0631\u0627\u0631\u064a","Long-term insulation protection for all project types by skilled professionals.","\u062d\u0645\u0627\u064a\u0629 \u0639\u0632\u0644 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0623\u0645\u062f \u0644\u062c\u0645\u064a\u0639 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0645\u0646 \u0642\u0650\u0628\u0644 \u0645\u062d\u062a\u0631\u0641\u064a\u0646 \u0645\u0647\u0631\u0629.",B.Hp),new A.fa("Concrete Curing Works","\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062e\u0631\u0633\u0627\u0646\u0629","Proper concrete treatment to resist corrosion and cracking throughout the lifetime.","\u0645\u0639\u0627\u0644\u062c\u0629 \u0635\u062d\u064a\u062d\u0629 \u0644\u0644\u062e\u0631\u0633\u0627\u0646\u0629 \u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u062a\u0622\u0643\u0644 \u0648\u0627\u0644\u062a\u0634\u0642\u0642 \u0637\u0648\u0627\u0644 \u062f\u0648\u0631\u0629 \u062d\u064a\u0627\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.",B.GW)],t.eB)
l=A.b([new A.hP("Awnings, Parking, and Asphalt Works","\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u0638\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0648\u0627\u0644\u0625\u0633\u0641\u0644\u062a",A.b(["https://picsum.photos/seed/p1a/600/400","https://picsum.photos/seed/p1b/600/400","https://picsum.photos/seed/p1c/600/400","https://picsum.photos/seed/p1d/600/400"],s)),new A.hP(e,d,A.b(["https://picsum.photos/seed/p2a/600/400","https://picsum.photos/seed/p2b/600/400","https://picsum.photos/seed/p2c/600/400","https://picsum.photos/seed/p2d/600/400"],s)),new A.hP("Gas Pipeline Infrastructure Project","\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0644\u062e\u0637\u0648\u0637 \u0623\u0646\u0627\u0628\u064a\u0628 \u0627\u0644\u063a\u0627\u0632",A.b(["https://picsum.photos/seed/p3a/600/400","https://picsum.photos/seed/p3b/600/400","https://picsum.photos/seed/p3c/600/400","https://picsum.photos/seed/p3d/600/400"],s))],t.R_)
k=A.b([new A.ez("Gas Pipeline Construction Project","\u0645\u0634\u0631\u0648\u0639 \u0625\u0646\u0634\u0627\u0621 \u062e\u0637 \u0623\u0646\u0627\u0628\u064a\u0628 \u0627\u0644\u063a\u0627\u0632","2024-01-15","https://picsum.photos/seed/n1/600/400","SCCL successfully completed the gas pipeline construction project, delivering high-quality infrastructure.","\u0623\u062a\u0645\u0651\u062a SCCL \u0628\u0646\u062c\u0627\u062d \u0645\u0634\u0631\u0648\u0639 \u0625\u0646\u0634\u0627\u0621 \u062e\u0637 \u0623\u0646\u0627\u0628\u064a\u0628 \u0627\u0644\u063a\u0627\u0632\u060c \u0648\u0633\u0644\u0651\u0645\u062a \u0628\u0646\u064a\u0629 \u062a\u062d\u062a\u064a\u0629 \u0639\u0627\u0644\u064a\u0629 \u0627\u0644\u062c\u0648\u062f\u0629."),new A.ez("Finishing of the Second Industrial Mosque in Dammam","\u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u0645\u0646 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u0635\u0646\u0627\u0639\u064a \u0627\u0644\u062b\u0627\u0646\u064a \u0628\u0627\u0644\u062f\u0645\u0627\u0645","2024-02-20","https://picsum.photos/seed/n2/600/400","We are proud to announce the completion of the Second Industrial Mosque in Dammam.","\u064a\u0633\u0639\u062f\u0646\u0627 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u0639\u0646 \u0625\u062a\u0645\u0627\u0645 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u0635\u0646\u0627\u0639\u064a \u0627\u0644\u062b\u0627\u0646\u064a \u0641\u064a \u0627\u0644\u062f\u0645\u0627\u0645."),new A.ez(e,d,"2024-03-10","https://picsum.photos/seed/n3/600/400","SCCL has been awarded the contract for establishing multiple factories in the Third Industrial City.","\u062d\u0635\u0644\u062a SCCL \u0639\u0644\u0649 \u0639\u0642\u062f \u0625\u0646\u0634\u0627\u0621 \u0645\u0635\u0627\u0646\u0639 \u0645\u062a\u0639\u062f\u062f\u0629 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0635\u0646\u0627\u0639\u064a\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629.")],t.V7)
